table netdev syswarden_hw_drop {
	set syswarden_whitelist { type ipv4_addr; flags interval; auto-merge; }
	set syswarden_whitelist6 { type ipv6_addr; flags interval; auto-merge; }
	set syswarden_zt_allowed { type ipv4_addr; flags interval; auto-merge; }
	set syswarden_zt_allowed6 { type ipv6_addr; flags interval; auto-merge; }
	set banned_ips { type ipv4_addr; flags timeout; }
	set banned_ips6 { type ipv6_addr; flags timeout; }
	set syswarden_blacklist { type ipv4_addr; flags interval; auto-merge; }
	set syswarden_blacklist6 { type ipv6_addr; flags interval; auto-merge; }
	chain ingress_frontline {
		type filter hook ingress device "swv0" priority -500; policy accept;
		ip saddr @syswarden_whitelist accept
		ip6 saddr @syswarden_whitelist6 accept
		ip saddr @banned_ips limit rate 2/second burst 5 packets log prefix "[SYSWARDEN-WAF-BLOCK] "
		ip saddr @banned_ips drop
		ip6 saddr @banned_ips6 limit rate 2/second burst 5 packets log prefix "[SYSWARDEN-WAF-BLOCK] "
		ip6 saddr @banned_ips6 drop
		ip protocol tcp tcp flags ! fin,syn,rst,psh,ack,urg counter drop
		ip protocol tcp tcp flags & (fin|syn|rst|psh|ack|urg) == fin|syn|rst|psh|ack|urg counter drop
		ip protocol tcp tcp flags & (fin|syn) == fin|syn counter drop
		ip protocol tcp tcp flags & (syn|rst) == syn|rst counter drop
		ip saddr @syswarden_blacklist limit rate 2/second burst 5 packets log prefix "[SYSWARDEN-BLOCK] "
		ip saddr @syswarden_blacklist drop
		ip6 saddr @syswarden_blacklist6 limit rate 2/second burst 5 packets log prefix "[SYSWARDEN-BLOCK] "
		ip6 saddr @syswarden_blacklist6 drop
	}
}

